const HOME = '/';
const ORIGIN = 'https://app.example';
const MAX_LENGTH = 2048;

export function safeRedirect(next) {
  if (typeof next !== 'string' || next.length === 0 || next.length > MAX_LENGTH) return HOME;
  if (!URL.canParse(next.trim(), ORIGIN)) return HOME;
  const candidate = new URL(next.trim(), ORIGIN);
  if (candidate.origin !== ORIGIN) return HOME;
  return candidate.href;
}

export function signInLocation(next) {
  return '/sign-in?next=' + encodeURIComponent(safeRedirect(next));
}

