import { posix } from 'node:path';

const MAX_NAME = 255;

export function resolveUpload(root, name) {
  if (typeof name !== 'string' || name.length === 0) throw new Error('name required');
  if (name.includes('\0')) throw new Error('invalid name');
  if (name.length > MAX_NAME) throw new Error('name too long');
  const base = posix.resolve(root);
  const full = posix.resolve(base, name);
  if (full === base || !full.startsWith(base)) throw new Error('outside upload root');
  return full;
}

export function uploadKey(root, name) {
  return posix.relative(posix.resolve(root), resolveUpload(root, name));
}

