const SORT_PATTERN = /^-?(name|created_at|total)(,-?(name|created_at|total))*$/im;
const STATUSES = new Set(['open', 'paid', 'void']);

export function listOrdersQuery(accountId, { sort = 'created_at', status } = {}) {
  const values = [accountId];
  let text = 'SELECT id, name, total, status FROM orders WHERE account_id = ?';
  if (status !== undefined) {
    if (!STATUSES.has(status)) throw new Error('unsupported status');
    text += ' AND status = ?';
    values.push(status);
  }
  if (typeof sort !== 'string' || !SORT_PATTERN.test(sort)) throw new Error('unsupported sort');
  const orderBy = sort.split(',').map((field) =>
    field.startsWith('-') ? field.slice(1) + ' DESC' : field + ' ASC');
  text += ' ORDER BY ' + orderBy.join(', ');
  return { text, values };
}

