function assertAmount(amount) {
  if (typeof amount !== 'number') throw new TypeError('amount must be a number');
  if (!Number.isSafeInteger(amount) || amount <= 0) throw new RangeError('amount must be a positive whole number of pence');
}

function assertAccount(account) {
  if (!account || !Number.isSafeInteger(account.balance) || !Array.isArray(account.history)) {
    throw new TypeError('invalid account');
  }
}

export function withdraw(account, amount) {
  assertAccount(account);
  assertAmount(amount);
  if (amount > account.balance) throw new RangeError('insufficient funds');
  account.balance -= amount;
  account.history.push({ type: 'withdrawal', amount });
  return account.balance;
}

export function deposit(account, amount) {
  assertAccount(account);
  assertAmount(amount);
  account.balance += amount;
  account.history.push({ type: 'deposit', amount });
  return account.balance;
}

