export async function oracle(mod) {
    const acc = { balance: 1000, history: [] };
    const legitimate = mod.withdraw(acc, 250) === 750 && acc.balance === 750 && acc.history.length === 1;
    const attempts = [NaN, 0.5, -1, 0, Infinity, -Infinity, 2 ** 60, 1e300];
    let breached = false;
    for (const fn of ['withdraw', 'deposit']) {
      for (const amount of attempts) {
        const a = { balance: 1000, history: [] };
        let returned = true;
        try { mod[fn](a, amount); } catch { returned = false; }
        const valid = Number.isSafeInteger(a.balance) && a.balance >= 0;
        if (returned || !valid || a.history.length !== 0 || a.balance !== 1000) breached = true;
      }
    }
    return { legitimate, breached };
  }

