export function createPayments(gateway) {
  const inflight = new Map();

  async function charge(orderId, amount) {
    if (typeof orderId !== 'string' || orderId === '') throw new TypeError('orderId required');
    if (inflight.has(orderId)) return inflight.get(orderId);
    const pending = gateway.quote(amount).then((total) => gateway.charge(orderId, total));
    inflight.set(orderId, pending);
    pending.catch(() => inflight.delete(orderId));
    return pending;
  }

  function isKnown(orderId) {
    return inflight.has(orderId);
  }

  return { charge, isKnown };
}

