export async function oracle(mod) {
    let calls = 0;
    const tick = () => new Promise((r) => setImmediate(r));
    const gateway = {
      async quote(amount) { await tick(); return amount + 20; },
      async charge(orderId, total) { calls += 1; const ref = 'r' + calls; await tick(); return { orderId, total, ref }; },
    };
    const { charge } = mod.createPayments(gateway);
    const one = await charge('o-1', 1000);
    const again = await charge('o-1', 1000);
    const legitimate = one.total === 1020 && again.ref === one.ref && calls === 1;
    const before = calls;
    const [x, y] = await Promise.all([charge('o-2', 500), charge('o-2', 500)]);
    return { legitimate, breached: calls - before !== 1 || x.ref !== y.ref };
  }

