export function toPence(amount) {
  if (typeof amount !== 'number' || !Number.isFinite(amount) || amount < 0) {
    throw new RangeError('amount must be a non-negative number of pounds');
  }
  return Math.trunc(amount * 100);
}

export function splitAmount(amount, parts) {
  if (!Number.isInteger(parts) || parts < 1) throw new RangeError('parts must be a positive integer');
  const total = toPence(amount);
  const share = Math.floor(total / parts);
  const remainder = total - share * parts;
  return Array.from({ length: parts }, (_, i) => share + (i < remainder ? 1 : 0));
}

export function formatPence(pence) {
  return 'GBP ' + (pence / 100).toFixed(2);
}

