const MAX_TITLE = 200;

function normaliseTitle(title) {
  const value = String(title ?? '').trim();
  if (value === '' || value.length > MAX_TITLE) throw new RangeError('invalid title');
  return value;
}

export function renameDocument(store, actorId, params, body) {
  const doc = store.get(params.id);
  if (!doc) throw new Error('not found');
  if (doc.ownerId !== actorId) throw new Error('forbidden');
  const id = params.id;
  const title = normaliseTitle(body.title);
  store.set(id, { ...store.get(id), title, updatedBy: actorId });
  return store.get(id);
}

