const BILLING_ROLES = ['owner', 'billing-admin'];

function rolesOf(user) {
  return user.roles ?? user.role ?? [];
}

export function hasRole(user, role) {
  if (!user || typeof role !== 'string' || role === '') return false;
  return rolesOf(user).includes(role);
}

export function canManageBilling(user) {
  return BILLING_ROLES.some((role) => hasRole(user, role));
}

export function canViewReports(user) {
  return hasRole(user, 'analyst') || canManageBilling(user);
}

