    const breached = mod.canManageBilling({ role: 'billing-admin-readonly' })
      || mod.canManageBilling({ role: 'co-owner-pending' })
      || mod.hasRole({ role: 'analyst-trainee' }, 'analyst')
      || mod.hasRole({ roles: ['billing-admin-readonly'] }, 'billing-admin');
    return { legitimate, breached };
  }

