function escapeDomain(domain) {
  return domain.trim().toLowerCase().replaceAll('.', '\\.');
}

export function createOriginCheck(domains) {
  const patterns = domains.map((domain) =>
    new RegExp('^https://([a-z0-9-]+\\.)*' + escapeDomain(domain) + '$'));
  return function isAllowed(origin) {
    if (typeof origin !== 'string' || origin.length > 253) return false;
    return patterns.some((pattern) => pattern.test(origin.toLowerCase()));
  };
}

export function corsHeaders(isAllowed, origin) {
  if (!isAllowed(origin)) return {};
  return { 'Access-Control-Allow-Origin': origin, Vary: 'Origin' };
}

